std::string random_string(size_t length) {
    auto randchar = []() -> char {
        const char charset[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        const size_t max_index = (sizeof(charset) - 1);
        return charset[rand() % max_index];
    };
    std::string str(length, 0);
    std::generate_n(str.begin(), length, randchar);
    return str;
}

WorldState create_complex_world() {
    WorldState world;
    world.world_id = 12345;
    world.seed = "random_seed_123";

    for (int i = 0; i < 5; ++i) {
        Guild g;
        g.name = "Guild_" + std::to_string(i);
        g.description = "Description for guild " + std::to_string(i);

        for (int j = 0; j < 50; ++j) {
            Character c;
            c.name = "Char_" + std::to_string(i) + "_" + std::to_string(j);
            c.level = rand() % 100 + 1;
            c.hp = rand() % 900 + 100;
            c.mp = rand() % 450 + 50;
            c.is_alive = true;
            c.position.x = rand() % 2000 - 1000;
            c.position.y = rand() % 100;
            c.position.z = rand() % 2000 - 1000;

            for (int k = 0; k < 5; ++k) c.skills.push_back(rand() % 50 + 1);

            for (int k = 0; k < 10; ++k) {
                Item it;
                it.id = k;
                it.name = "Item_" + std::to_string(k);
                it.value = rand() % 490 + 10;
                it.weight = rand() % 20 + 1;
                it.rarity = "Common";
                c.inventory.push_back(it);
            }
            g.members.push_back(c);
        }
        world.guilds.push_back(g);
    }

    for (int i = 0; i < 20; ++i) {
        Item it;
        it.id = i;
        it.name = "Loot_" + std::to_string(i);
        it.value = rand() % 900 + 100;
        it.weight = rand() % 45 + 5;
        it.rarity = "Rare";
        world.loot_table.push_back(it);
    }
    return world;
}


void to_json(json& j, const Vec3& p) { j = json{{"x", p.x}, {"y", p.y}, {"z", p.z}}; }
void to_json(json& j, const Item& p) { j = json{{"id", p.id}, {"name", p.name}, {"value", p.value}, {"weight", p.weight}, {"rarity", p.rarity}}; }
void to_json(json& j, const Character& p) { j = json{{"name", p.name}, {"level", p.level}, {"hp", p.hp}, {"mp", p.mp}, {"is_alive", p.is_alive}, {"position", p.position}, {"skills", p.skills}, {"inventory", p.inventory}}; }
void to_json(json& j, const Guild& p) { j = json{{"name", p.name}, {"description", p.description}, {"members", p.members}}; }
void to_json(json& j, const WorldState& p) { j = json{{"world_id", p.world_id}, {"seed", p.seed}, {"guilds", p.guilds}, {"loot_table", p.loot_table}}; }

void from_json(const json& j, Vec3& p) { j.at("x").get_to(p.x); j.at("y").get_to(p.y); j.at("z").get_to(p.z); }




